//! Offline tests. Fixtures (tests/fixtures.json) are generated by scripts/gen-fixtures.ts with viem + noble, independent of the Rust code.
use chainsig_spike::{Spike, SignatureResponse};
use near_sdk::json_types::U128;
use near_sdk::serde_json::{self, Value};
use near_sdk::test_utils::{get_logs, VMContextBuilder};
use near_sdk::{testing_env, AccountId, PromiseError, PromiseOrValue};

fn fx() -> Value {
    serde_json::from_str(include_str!("fixtures.json")).unwrap()
}
fn acct(s: &str) -> AccountId {
    s.parse().unwrap()
}
fn as_owner() {
    testing_env!(VMContextBuilder::new().predecessor_account_id(acct("titleshot.testnet")).current_account_id(acct("cs.titleshot.testnet")).build());
}
fn new_contract(with_address: bool) -> Spike {
    as_owner();
    let mut c = Spike::new(acct("titleshot.testnet"), acct("v1.signer-prod.testnet"), "belt-1".into(), 0, 84532);
    if with_address {
        c.set_address(fx()["address"].as_str().unwrap().to_string());
    }
    c
}
fn s(v: &Value, k: &str) -> String {
    v[k].as_str().unwrap().to_string()
}
fn u(f: &Value, k: &str) -> U128 {
    U128(f[k].as_str().unwrap().parse().unwrap())
}
fn start(c: &mut Spike, id: u64, v: &Value) -> PromiseOrValue<Option<String>> {
    let f = fx();
    c.sign_payout(id, s(&f, "to"), u(&f, "value_wei"), v["nonce"].as_u64().unwrap(), u(&f, "max_fee"), u(&f, "max_prio"), f["gas_limit"].as_u64().unwrap())
}
fn resp(v: &Value) -> Result<SignatureResponse, PromiseError> {
    // The live signer's JSON shape, captured from a real call (see RESULT.md).
    let j = format!(r#"{{"scheme":"Secp256k1","big_r":{{"affine_point":"{}"}},"s":{{"scalar":"{}"}},"recovery_id":{}}}"#, s(v, "big_r"), s(v, "s"), v["recovery_id"]);
    Ok(serde_json::from_str(&j).unwrap())
}

#[test]
fn preview_matches_viem() {
    let c = new_contract(true);
    let f = fx();
    for k in ["plain", "leading_zero"] {
        let v = &f[k];
        let p = c.preview(s(&f, "to"), u(&f, "value_wei"), v["nonce"].as_u64().unwrap(), u(&f, "max_fee"), u(&f, "max_prio"), 21000);
        assert_eq!(p["unsigned"], v["unsigned"], "{k}");
        assert_eq!(p["digest"], v["digest"], "{k}");
    }
}

#[test]
fn signs_and_assembles_viem_identical_raw_tx() {
    for (id, k) in [(101u64, "plain"), (102, "leading_zero")] {
        // testing_env! carries storage across contracts in one thread, hence a distinct payout id per vector.
        let mut c = new_contract(true);
        let v = fx()[k].clone();
        assert!(matches!(start(&mut c, id, &v), PromiseOrValue::Promise(_)));
        assert!(c.is_pending(id));
        let raw = c.on_signed(id, resp(&v)).expect("signed");
        assert_eq!(raw, s(&v, "raw"), "{k}");
        assert_eq!(c.get_raw_tx(id), Some(raw));
        assert!(!c.is_pending(id));
        assert!(get_logs().iter().any(|l| l.starts_with("EVENT_JSON:") && l.contains("payout_signed")));
    }
}

#[test]
fn replay_returns_stored_tx_without_new_signature() {
    let mut c = new_contract(true);
    let v = fx()["plain"].clone();
    start(&mut c, 9, &v);
    c.on_signed(9, resp(&v)).unwrap();
    match start(&mut c, 9, &v) {
        PromiseOrValue::Value(Some(raw)) => assert_eq!(raw, s(&v, "raw")),
        _ => panic!("expected stored value, not a new signer promise"),
    }
    assert!(get_logs().iter().any(|l| l.contains("payout_replayed")));
}

#[test]
#[should_panic(expected = "already signed with different parameters")]
fn same_id_different_params_is_refused() {
    let mut c = new_contract(true);
    let v = fx()["plain"].clone();
    start(&mut c, 3, &v);
    c.on_signed(3, resp(&v)).unwrap();
    let mut other = v.clone();
    other["nonce"] = Value::from(8);
    start(&mut c, 3, &other);
}

#[test]
#[should_panic(expected = "being signed")]
fn second_call_while_pending_is_refused() {
    let mut c = new_contract(true);
    let v = fx()["plain"].clone();
    start(&mut c, 4, &v);
    start(&mut c, 4, &v);
}

#[test]
#[should_panic(expected = "owner only")]
fn non_owner_cannot_sign() {
    let mut c = new_contract(true);
    testing_env!(VMContextBuilder::new().predecessor_account_id(acct("mallory.testnet")).build());
    start(&mut c, 5, &fx()["plain"].clone());
}

#[test]
fn signer_error_clears_pending_so_payout_can_retry() {
    let mut c = new_contract(true);
    let v = fx()["plain"].clone();
    start(&mut c, 6, &v);
    assert_eq!(c.on_signed(6, Err(PromiseError::Failed)), None);
    assert!(!c.is_pending(6) && c.get_raw_tx(6).is_none());
    assert!(get_logs().iter().any(|l| l.contains("payout_sign_failed") && l.contains("signer_error")));
    start(&mut c, 6, &v);
    assert_eq!(c.on_signed(6, resp(&v)).unwrap(), s(&v, "raw"));
}

#[test]
fn signature_from_the_wrong_key_is_rejected_before_broadcast() {
    let mut c = new_contract(false);
    c.set_address("0x00000000000000000000000000000000000000aa".into());
    let v = fx()["plain"].clone();
    start(&mut c, 7, &v);
    assert_eq!(c.on_signed(7, resp(&v)), None);
    assert!(get_logs().iter().any(|l| l.contains("recovered_address_mismatch")));
    assert!(c.get_raw_tx(7).is_none());
}

#[test]
fn high_s_signature_is_rejected() {
    let mut c = new_contract(true);
    let v = fx()["high_s"].clone();
    start(&mut c, 8, &v);
    assert_eq!(c.on_signed(8, resp(&v)), None);
    assert!(get_logs().iter().any(|l| l.contains("recovered_address_mismatch")));
}

#[test]
fn input_validation() {
    let f = fx();
    let bad = |to: &str, gas: u64, fee: u128, prio: u128| {
        let mut c = new_contract(true);
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            c.sign_payout(1, to.into(), U128(1), 0, U128(fee), U128(prio), gas);
        }))
        .is_err()
    };
    let to = s(&f, "to");
    assert!(bad("1111111111111111111111111111111111111111", 21000, 2, 1), "missing 0x");
    assert!(bad("0x1234", 21000, 2, 1), "short address");
    assert!(bad("0xzz11111111111111111111111111111111111111", 21000, 2, 1), "non hex");
    assert!(bad(&to, 20999, 2, 1), "gas below 21000");
    assert!(bad(&to, 21000, 1, 2), "fee below priority");
    assert!(!bad(&to, 21000, 2, 1), "valid call is accepted");
}
